const productFilter={search:'',status:'',online:''};

function renderCatalogProducts(){
  const rows=catalogProducts.filter(product=>(!productFilter.search||(product.name+' '+product.sku).toLowerCase().includes(productFilter.search.toLowerCase()))&&(!productFilter.status||product.status===productFilter.status)&&(!productFilter.online||product.online===productFilter.online));
  const published=catalogProducts.filter(product=>product.online==='Published').length;
  const low=catalogProducts.filter(product=>product.stock!==null&&product.stock<=7).length;
  const pageSize=catalogManagementState.pageSize||5,pageCount=Math.max(1,Math.ceil(rows.length/pageSize));catalogManagementState.page=Math.min(catalogManagementState.page||1,pageCount);const visibleRows=rows.slice((catalogManagementState.page-1)*pageSize,catalogManagementState.page*pageSize);
  return `<div class="catalog-products-mock"><header class="catalog-products-header"><div><span class="eyebrow">PRODUCT CATALOG</span><h1>Products</h1><p>Manage product definitions here and use the Inventory module as the source of truth for live stock.</p></div><a class="btn primary" href="#/app/catalog/products/new">+ Add Product</a></header>
  <div class="catalog-product-summary"><div><span>Published</span><strong>${published}</strong><small>Available online</small></div><div><span>Inventory Low</span><strong>${low}</strong><small>Across active locations</small></div><div><span>Page Size</span><strong>${pageSize}</strong><small>Products per page</small></div><div class="catalog-summary-note"><span>Catalog health</span><strong>${catalogProducts.length} product definitions</strong><small>Sample assortment · Stravix Group BD</small></div></div>
  <section class="catalog-products-panel"><div class="catalog-products-panel-head"><div><h2>Find Products</h2><p>Search by name or SKU, then narrow results by status.</p></div><span class="catalog-product-count">${rows.length} results</span></div><div class="catalog-product-filters"><label><span>Search</span><input id="catalog-search" data-product-filter="search" type="search" placeholder="Search by product name or SKU…" value="${esc(productFilter.search)}"></label><label><span>Status</span><select data-product-filter="status"><option value="">All Status</option>${['Active','Inactive','Deleted'].map(value=>`<option ${productFilter.status===value?'selected':''}>${value}</option>`).join('')}</select></label><label><span>Online state</span><select data-product-filter="online"><option value="">All Online States</option>${['Published','Draft','Scheduled','Archived','Offline'].map(value=>`<option ${productFilter.online===value?'selected':''}>${value}</option>`).join('')}</select></label><button class="btn" data-product-clear type="button">Clear</button></div>
  ${rows.length?`<div class="catalog-products-table-wrap"><table class="catalog-products-table"><thead><tr><th>Product</th><th>SKU</th><th>Type</th><th>Category</th><th>Status</th><th>Online state</th><th>Stock</th><th>Price</th><th>Updated</th><th aria-label="Actions"></th></tr></thead><tbody>${visibleRows.map(product=>`<tr><td><a class="catalog-product-identity" href="#/app/catalog/products/${product.sku}"><span class="product-monogram product-${product.tone}">${product.initials}</span><span><strong>${esc(product.name)}</strong><small>${esc(product.brand)}</small></span></a></td><td class="catalog-product-sku">${product.sku}</td><td>${product.type}</td><td>${product.category}</td><td><span class="catalog-product-badge active">${product.status}</span></td><td><span class="catalog-product-badge ${product.online.toLowerCase()}">${product.online}</span></td><td><span class="stock-value ${product.stock!==null&&product.stock<=7?'low':''}">${product.stock===null?'Service':product.stock+' in stock'}</span></td><td class="catalog-product-price">৳ ${product.price.toFixed(2)}</td><td>${product.updated}</td><td><a class="catalog-product-view" href="#/app/catalog/products/${product.sku}">View ↗</a></td></tr>`).join('')}</tbody></table></div>${window.suitePagination(rows.length,catalogManagementState.page,pageSize,'products')}`:`<div class="order-empty"><span aria-hidden="true">⌕</span><strong>No products found</strong><p>Try a different name, SKU, status, or online state.</p><button class="btn" data-product-clear type="button">Clear filters</button></div>`}</section></div>`;
}

root.addEventListener('input',event=>{const key=event.target.dataset.productFilter;if(!key)return;productFilter[key]=event.target.value;if(key==='search'){catalogManagementState.page=1;render(true)}});
root.addEventListener('change',event=>{const key=event.target.dataset.productFilter;if(!key)return;productFilter[key]=event.target.value;catalogManagementState.page=1;render()});
root.addEventListener('click',event=>{if(!event.target.closest('[data-product-clear]'))return;for(const key of Object.keys(productFilter))productFilter[key]='';catalogManagementState.page=1;render()});

function renderCatalogProductDetail(sku){
  const product=catalogProducts.find(item=>item.sku===sku);
  if(!product)return '<div class="order-empty"><strong>Product not found</strong><a class="btn" href="#/app/catalog/products">Back to Products</a></div>';
  const service=product.type==='Service',reserved=service?0:Math.min(3,Math.floor(product.stock/8)),onHand=service?0:product.stock+reserved;
  const info=(label,value)=>`<div class="catalog-detail-info"><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`;
  const card=(title,note,body)=>`<section class="catalog-detail-card"><div class="catalog-detail-card-head"><h2>${title}</h2><span>${note}</span></div>${body}</section>`;
  const supplier=product.brand==='Northline'?'Harbor Textiles Ltd.':'Metro Trade Supply';
  const variants=product.sku==='APP-1042'?`<div class="catalog-detail-variants"><div><strong>APP-1042-S</strong><span>Sand / S · Active</span><small>Price override: — · Managed via Inventory for stock</small></div><div><strong>APP-1042-M</strong><span>Sand / M · Active</span><small>Price override: — · Managed via Inventory for stock</small></div></div>`:'<p class="catalog-detail-copy">This product has one standard SKU. Stock remains inventory-owned.</p>';
  return `<div class="catalog-product-detail"><header class="catalog-detail-hero"><div><div class="catalog-detail-crumb"><a href="#/app/catalog/products">Products</a><span>/</span><strong>${esc(product.name)}</strong></div><span class="eyebrow">CATALOG PRODUCT</span><h1>${esc(product.name)}</h1><p>Catalog, commerce, and inventory visibility for ${esc(product.name.toLowerCase())} across Stravix Group BD.</p><div class="catalog-detail-pills"><span>${esc(product.status)}</span><span>${esc(product.online)}</span><span>${service?'Service':product.stock<=7?'Low stock':'In stock'}</span><span>${esc(product.type)}</span>${product.sku==='APP-1042'?'<span>2 variants</span>':''}</div></div><div class="catalog-detail-actions"><a class="btn primary" href="#/app/catalog/products/${sku}/edit/overview">Edit Product</a><a class="btn" href="#/app/inventory/adjustments">Adjust Inventory</a><a class="btn" href="#/app/catalog/products">Back to List</a></div></header>
  <div class="catalog-detail-stats">${[['Available',service?'Service':product.stock,'Inventory-owned sellable quantity'],['On Hand',service?'—':onHand,'Across tracked facilities'],['Reserved',reserved,'Committed to active workflows'],['Online Sellable',service?'—':Math.max(0,product.stock-4),'Available to ecommerce channels'],['Facilities',service?'—':2,'2 active branches carrying stock']].map(([label,value,note])=>`<article><span>${label}</span><strong>${value}</strong><small>${note}</small></article>`).join('')}</div>
  <div class="catalog-detail-columns"><main>
  ${card('Commercial Snapshot','Definition, pricing, publication, and sellability',`<div class="catalog-detail-info-grid">${info('SKU',product.sku)}${info('Slug',product.name.toLowerCase().replace(/\s+/g,'-'))}${info('Price','৳ '+product.price.toFixed(2))}${info('Sale Price','—')}${info('Compare At','—')}${info('Cost Price','৳ '+(product.price*.62).toFixed(2))}${info('Category',product.category)}${info('Subcategory','—')}${info('Brand',product.brand)}${info('Supplier',supplier)}${info('Storefront status',product.online)}</div>`)}
  ${card('Inventory Position','Read-only inventory signal sourced from Inventory',`<div class="catalog-detail-callout"><strong>Inventory is the source of truth.</strong><p>Catalog keeps thresholds and policy. Live quantities, reservations, and facility balances are managed in Inventory workflows.</p></div><div class="catalog-detail-info-grid">${info('Tracking Enabled',service?'No':'Yes')}${info('Backorders','Blocked')}${info('Low Stock Threshold','8')}${info('Reorder Level','12')}${info('In Stock',service?'Not applicable':'Yes')}${info('Low Stock',product.stock!==null&&product.stock<=7?'Yes':'No')}</div>${service?'':`<div class="catalog-facility"><div><strong>DT-01 · Downtown Branch</strong><small>Branch policy configured</small><span>Available ${Math.max(0,product.stock-8)} · Online ${Math.max(0,product.stock-11)}</span></div><div><strong>NB-02 · North Branch</strong><small>Branch policy configured</small><span>Available ${Math.min(product.stock,8)} · Online ${Math.min(product.stock,7)}</span></div></div>`}`)}
  ${card('Catalog Narrative','Descriptions, tags, and collection placement',`<p class="catalog-detail-copy">${esc(product.name)} is part of the curated Stravix sample assortment. Product definition and selling content live in Catalog while availability is managed in Inventory.</p><div class="catalog-detail-chips"><span>Tags</span><b>${esc(product.category)}</b><b>${esc(product.brand)}</b></div><div class="catalog-detail-chips"><span>Collections</span><b>Everyday Essentials</b></div>`)}
  ${card('Variants','Variant definitions only. Stock remains inventory-owned.',variants)}
  ${card('Supplier Links','Procurement relationships for this product',`<div class="catalog-detail-table-wrap"><table><thead><tr><th>Supplier</th><th>Supplier SKU</th><th>Cost</th><th>Lead Time</th><th>Status</th></tr></thead><tbody><tr><td><strong>${esc(supplier)}</strong><small>Primary supplier</small></td><td>SUP-${esc(product.sku)}</td><td>৳ ${(product.price*.62).toFixed(2)}</td><td>14 days</td><td><span class="catalog-product-badge active">Active</span></td></tr></tbody></table></div>`)}
  </main><aside>
  ${card('Operations','Fast next steps',`<div class="catalog-detail-operations"><a href="#/app/inventory/adjustments"><strong>Adjust inventory</strong><span>Post a facility-aware stock correction or write-off.</span></a><a href="#/app/inventory/workspace"><strong>Open inventory workspace</strong><span>Review balances, ledger movement, and replenishment signals.</span></a><a href="#/app/catalog/products/${sku}/edit/variants"><strong>Manage variants</strong><span>Update SKU definitions, options, and active status.</span></a></div>`)}
  ${card('Publishing','Storefront readiness',`<div class="catalog-detail-info-grid compact">${info('Main image','Configured')}${info('Gallery assets','3')}${info('Meta title','Ready')}${info('Meta description','Ready')}${info('Published at','22 Sep 2026')}${info('Release date','—')}</div>`)}
  ${card('Physical Profile','Shipping and compliance context',`<div class="catalog-detail-info-grid compact">${info('Requires shipping',service?'No':'Yes')}${info('Weight',service?'—':'0.4 kg')}${info('Dimensions',service?'—':'32 × 24 × 3 cm')}${info('Country of origin','Bangladesh')}${info('HS code',service?'—':'6205.20')}${info('Certificates','—')}</div>`)}
  ${card('Record History','Audit-friendly timestamps',`<div class="catalog-detail-info-grid compact">${info('Created','18 Sep 2026, 9:42 AM')}${info('Updated',product.updated)}${info('Availability date','20 Sep 2026')}${info('Expiry date','—')}${info('Product id',product.sku)}</div>`)}
  </aside></div></div>`;
}
